### 32.16 예제 프로그램 (Example Programs)

#### 예제 1: 기본 연결 및 쿼리 실행

```c
#include <stdio.h>
#include <stdlib.h>
#include <libpq-fe.h>

static void
exit_nicely(PGconn *conn)
{
    PQfinish(conn);
    exit(1);
}

int
main(int argc, char argv)
{
    const char *conninfo;
    PGconn     *conn;
    PGresult   *res;
    int         nFields;
    int         i, j;

    /* 연결 정보 설정 */
    if (argc > 1)
        conninfo = argv[1];
    else
        conninfo = "dbname = postgres";

    /* 데이터베이스에 연결 */
    conn = PQconnectdb(conninfo);

    /* 백엔드 연결이 성공적으로 이루어졌는지 확인 */
    if (PQstatus(conn) != CONNECTION_OK)
    {
        fprintf(stderr, "데이터베이스 연결 실패: %s",
                PQerrorMessage(conn));
        exit_nicely(conn);
    }

    /* 보안 설정을 위해 search_path 설정 */
    res = PQexec(conn, "SELECT pg_catalog.set_config('search_path', '', false)");
    if (PQresultStatus(res) != PGRES_TUPLES_OK)
    {
        fprintf(stderr, "SET 실패: %s", PQerrorMessage(conn));
        PQclear(res);
        exit_nicely(conn);
    }
    PQclear(res);

    /* 트랜잭션 블록 시작 */
    res = PQexec(conn, "BEGIN");
    if (PQresultStatus(res) != PGRES_COMMAND_OK)
    {
        fprintf(stderr, "BEGIN 명령 실패: %s", PQerrorMessage(conn));
        PQclear(res);
        exit_nicely(conn);
    }
    PQclear(res);

    /* 커서로 데이터 가져오기 */
    res = PQexec(conn, "DECLARE myportal CURSOR FOR select * from pg_database");
    if (PQresultStatus(res) != PGRES_COMMAND_OK)
    {
        fprintf(stderr, "DECLARE CURSOR 실패: %s", PQerrorMessage(conn));
        PQclear(res);
        exit_nicely(conn);
    }
    PQclear(res);

    res = PQexec(conn, "FETCH ALL in myportal");
    if (PQresultStatus(res) != PGRES_TUPLES_OK)
    {
        fprintf(stderr, "FETCH ALL 실패: %s", PQerrorMessage(conn));
        PQclear(res);
        exit_nicely(conn);
    }

    /* 먼저 속성 이름 출력 */
    nFields = PQnfields(res);
    for (i = 0; i < nFields; i++)
        printf("%-15s", PQfname(res, i));
    printf("\n\n");

    /* 다음으로 행 출력 */
    for (i = 0; i < PQntuples(res); i++)
    {
        for (j = 0; j < nFields; j++)
            printf("%-15s", PQgetvalue(res, i, j));
        printf("\n");
    }

    PQclear(res);

    /* 포털 닫기 */
    res = PQexec(conn, "CLOSE myportal");
    PQclear(res);

    /* 트랜잭션 종료 */
    res = PQexec(conn, "END");
    PQclear(res);

    /* 데이터베이스 연결 닫기 및 정리 */
    PQfinish(conn);

    return 0;
}
```

#### 예제 2: 파라미터화된 쿼리

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libpq-fe.h>

int
main(int argc, char argv)
{
    PGconn     *conn;
    PGresult   *res;
    const char *conninfo = "dbname=postgres";

    /* 데이터베이스에 연결 */
    conn = PQconnectdb(conninfo);
    if (PQstatus(conn) != CONNECTION_OK)
    {
        fprintf(stderr, "연결 실패: %s", PQerrorMessage(conn));
        PQfinish(conn);
        return 1;
    }

    /* 파라미터화된 쿼리 예제 */
    const char *paramValues[1];
    paramValues[0] = "postgres";

    res = PQexecParams(conn,
                       "SELECT * FROM pg_database WHERE datname = $1",
                       1,       /* 파라미터 수 */
                       NULL,    /* 파라미터 타입 자동 추론 */
                       paramValues,
                       NULL,    /* 텍스트 파라미터이므로 길이 불필요 */
                       NULL,    /* 기본적으로 모두 텍스트 */
                       0);      /* 텍스트 형식으로 결과 요청 */

    if (PQresultStatus(res) != PGRES_TUPLES_OK)
    {
        fprintf(stderr, "쿼리 실패: %s", PQerrorMessage(conn));
        PQclear(res);
        PQfinish(conn);
        return 1;
    }

    /* 결과 출력 */
    int nrows = PQntuples(res);
    int ncols = PQnfields(res);

    printf("%d개 행 조회됨\n", nrows);

    for (int i = 0; i < nrows; i++)
    {
        printf("행 %d:\n", i);
        for (int j = 0; j < ncols; j++)
        {
            printf("  %s = %s\n", PQfname(res, j), PQgetvalue(res, i, j));
        }
    }

    PQclear(res);
    PQfinish(conn);
    return 0;
}
```

#### 예제 3: 비동기 알림 처리

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/time.h>
#include <sys/types.h>
#include <libpq-fe.h>

int
main(int argc, char argv)
{
    PGconn     *conn;
    PGresult   *res;
    PGnotify   *notify;
    int         sock;

    conn = PQconnectdb("dbname=postgres");
    if (PQstatus(conn) != CONNECTION_OK)
    {
        fprintf(stderr, "연결 실패: %s", PQerrorMessage(conn));
        PQfinish(conn);
        return 1;
    }

    /* LISTEN 명령 실행 */
    res = PQexec(conn, "LISTEN TBL2");
    if (PQresultStatus(res) != PGRES_COMMAND_OK)
    {
        fprintf(stderr, "LISTEN 실패: %s", PQerrorMessage(conn));
        PQclear(res);
        PQfinish(conn);
        return 1;
    }
    PQclear(res);

    /* 소켓 가져오기 */
    sock = PQsocket(conn);

    printf("알림 대기 중...\n");

    while (1)
    {
        fd_set      input_mask;

        FD_ZERO(&input_mask);
        FD_SET(sock, &input_mask);

        /* select()로 입력 대기 */
        if (select(sock + 1, &input_mask, NULL, NULL, NULL) < 0)
        {
            fprintf(stderr, "select() 실패: %s\n", strerror(errno));
            break;
        }

        /* 서버에서 입력 읽기 */
        PQconsumeInput(conn);

        /* 알림 확인 */
        while ((notify = PQnotifies(conn)) != NULL)
        {
            printf("백엔드 PID %d에서 비동기 알림 '%s' 수신, 페이로드: '%s'\n",
                   notify->be_pid, notify->relname, notify->extra);
            PQfreemem(notify);
        }
    }

    PQfinish(conn);
    return 0;
}
```

