### 5. 예제 프로그램 (Example Program)

다음은 libpq로 대용량 객체 인터페이스를 사용하는 C 예제 프로그램임. PostgreSQL 소스 배포의 `src/test/examples/testlo.c`에서도 확인 가능.

```c
/*-----------------------------------------------------------------
 *
 * testlo.c
 *    libpq를 사용한 대용량 객체 테스트 프로그램
 *
 *-----------------------------------------------------------------
 */
#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

#include "libpq-fe.h"
#include "libpq/libpq-fs.h"

#define BUFSIZE 1024

/*
 * importFile - 파일을 대용량 객체로 임포트
 */
static Oid
importFile(PGconn *conn, char *filename)
{
    Oid         lobjId;
    int         lobj_fd;
    char        buf[BUFSIZE];
    int         nbytes, tmp;
    int         fd;

    /* 읽을 파일 열기 */
    fd = open(filename, O_RDONLY, 0666);
    if (fd < 0) {
        fprintf(stderr, "Unix 파일 \"%s\"을 열 수 없습니다\n", filename);
        return InvalidOid;
    }

    /* 대용량 객체 생성 */
    lobjId = lo_creat(conn, INV_READ | INV_WRITE);
    if (lobjId == InvalidOid) {
        fprintf(stderr, "대용량 객체를 생성할 수 없습니다\n");
        close(fd);
        return InvalidOid;
    }

    lobj_fd = lo_open(conn, lobjId, INV_WRITE);

    /* Unix 파일에서 읽어서 대용량 객체에 쓰기 */
    while ((nbytes = read(fd, buf, BUFSIZE)) > 0) {
        tmp = lo_write(conn, lobj_fd, buf, nbytes);
        if (tmp < nbytes) {
            fprintf(stderr, "\"%s\" 읽기 중 오류 발생\n", filename);
            break;
        }
    }

    close(fd);
    lo_close(conn, lobj_fd);

    return lobjId;
}

/*
 * pickout - 대용량 객체의 특정 범위 읽기
 */
static void
pickout(PGconn *conn, Oid lobjId, int start, int len)
{
    int         lobj_fd;
    char       *buf;
    int         nbytes, nread;

    lobj_fd = lo_open(conn, lobjId, INV_READ);
    if (lobj_fd < 0) {
        fprintf(stderr, "대용량 객체 %u를 열 수 없습니다\n", lobjId);
        return;
    }

    lo_lseek(conn, lobj_fd, start, SEEK_SET);
    buf = malloc(len + 1);

    nread = 0;
    while (len - nread > 0) {
        nbytes = lo_read(conn, lobj_fd, buf, len - nread);
        if (nbytes <= 0)
            break;  /* 더 이상 데이터 없음 */
        buf[nbytes] = '\0';
        fprintf(stderr, ">>> %s", buf);
        nread += nbytes;
    }

    free(buf);
    fprintf(stderr, "\n");
    lo_close(conn, lobj_fd);
}

/*
 * overwrite - 대용량 객체의 특정 범위 덮어쓰기
 */
static void
overwrite(PGconn *conn, Oid lobjId, int start, int len)
{
    int         lobj_fd;
    char       *buf;
    int         nbytes, nwritten, i;

    lobj_fd = lo_open(conn, lobjId, INV_WRITE);
    if (lobj_fd < 0) {
        fprintf(stderr, "대용량 객체 %u를 열 수 없습니다\n", lobjId);
        return;
    }

    lo_lseek(conn, lobj_fd, start, SEEK_SET);
    buf = malloc(len + 1);

    /* 'X' 문자로 채우기 */
    for (i = 0; i < len; i++)
        buf[i] = 'X';
    buf[i] = '\0';

    nwritten = 0;
    while (len - nwritten > 0) {
        nbytes = lo_write(conn, lobj_fd, buf + nwritten, len - nwritten);
        if (nbytes <= 0) {
            fprintf(stderr, "\n쓰기 실패!\n");
            break;
        }
        nwritten += nbytes;
    }

    free(buf);
    fprintf(stderr, "\n");
    lo_close(conn, lobj_fd);
}

/*
 * exportFile - 대용량 객체를 파일로 내보내기
 */
static void
exportFile(PGconn *conn, Oid lobjId, char *filename)
{
    int         lobj_fd;
    char        buf[BUFSIZE];
    int         nbytes, tmp;
    int         fd;

    /* 대용량 객체 열기 */
    lobj_fd = lo_open(conn, lobjId, INV_READ);
    if (lobj_fd < 0) {
        fprintf(stderr, "대용량 객체 %u를 열 수 없습니다\n", lobjId);
        return;
    }

    /* 출력 파일 열기 */
    fd = open(filename, O_CREAT | O_WRONLY | O_TRUNC, 0666);
    if (fd < 0) {
        fprintf(stderr, "Unix 파일 \"%s\"을 열 수 없습니다\n", filename);
        lo_close(conn, lobj_fd);
        return;
    }

    /* 대용량 객체에서 읽어서 Unix 파일에 쓰기 */
    while ((nbytes = lo_read(conn, lobj_fd, buf, BUFSIZE)) > 0) {
        tmp = write(fd, buf, nbytes);
        if (tmp < nbytes) {
            fprintf(stderr, "\"%s\" 쓰기 중 오류 발생\n", filename);
            break;
        }
    }

    lo_close(conn, lobj_fd);
    close(fd);
}

static void
exit_nicely(PGconn *conn)
{
    PQfinish(conn);
    exit(1);
}

int
main(int argc, char **argv)
{
    char       *in_filename, *out_filename;
    char       *database;
    Oid         lobjOid;
    PGconn     *conn;
    PGresult   *res;

    if (argc != 4) {
        fprintf(stderr, "사용법: %s database_name in_filename out_filename\n",
                argv[0]);
        exit(1);
    }

    database = argv[1];
    in_filename = argv[2];
    out_filename = argv[3];

    /* 연결 설정 */
    conn = PQsetdb(NULL, NULL, NULL, NULL, database);

    /* 백엔드 연결 확인 */
    if (PQstatus(conn) != CONNECTION_OK) {
        fprintf(stderr, "%s", PQerrorMessage(conn));
        exit_nicely(conn);
    }

    /* 보안을 위한 search_path 설정 */
    res = PQexec(conn,
                 "SELECT pg_catalog.set_config('search_path', '', false)");
    if (PQresultStatus(res) != PGRES_TUPLES_OK) {
        fprintf(stderr, "SET 실패: %s", PQerrorMessage(conn));
        PQclear(res);
        exit_nicely(conn);
    }
    PQclear(res);

    /* 트랜잭션 시작 */
    res = PQexec(conn, "BEGIN");
    PQclear(res);

    printf("파일 \"%s\" 임포트 중...\n", in_filename);
    lobjOid = lo_import(conn, in_filename);

    if (lobjOid == InvalidOid) {
        fprintf(stderr, "%s\n", PQerrorMessage(conn));
    } else {
        printf("\t대용량 객체 %u로 저장됨.\n", lobjOid);

        printf("대용량 객체의 바이트 1000-2000 읽기\n");
        pickout(conn, lobjOid, 1000, 1000);

        printf("대용량 객체의 바이트 1000-2000을 'X'로 덮어쓰기\n");
        overwrite(conn, lobjOid, 1000, 1000);

        printf("대용량 객체를 파일 \"%s\"로 내보내기...\n", out_filename);
        if (lo_export(conn, lobjOid, out_filename) < 0) {
            fprintf(stderr, "%s\n", PQerrorMessage(conn));
        }
    }

    /* 트랜잭션 종료 */
    res = PQexec(conn, "END");
    PQclear(res);

    PQfinish(conn);
    return 0;
}
```

#### 프로그램 컴파일 및 실행

```bash
# 컴파일
gcc -o testlo testlo.c -I$(pg_config --includedir) -L$(pg_config --libdir) -lpq

# 실행
./testlo mydb input.txt output.txt
```

#### 출력 예시

```
파일 "input.txt" 임포트 중...
    대용량 객체 24528로 저장됨.
대용량 객체의 바이트 1000-2000 읽기
>>> [해당 범위의 내용 출력]
대용량 객체의 바이트 1000-2000을 'X'로 덮어쓰기

대용량 객체를 파일 "output.txt"로 내보내기...
```

