#### 7.1 완전한 FDW 구현 예제

다음은 간단한 CSV 파일 FDW의 완전한 구현 예제임.

##### 헤더 파일 (my_csv_fdw.h)

```c
#ifndef MY_CSV_FDW_H
#define MY_CSV_FDW_H

#include "postgres.h"
#include "fmgr.h"
#include "foreign/fdwapi.h"
#include "foreign/foreign.h"
#include "optimizer/pathnode.h"
#include "optimizer/planmain.h"
#include "optimizer/restrictinfo.h"
#include "utils/rel.h"

/* 계획 상태 구조체 */
typedef struct MyCsvFdwPlanState
{
    char       *filename;       /* CSV 파일 경로 */
    List       *options;        /* 옵션 리스트 */
    BlockNumber pages;          /* 추정 페이지 수 */
    double      ntuples;        /* 추정 튜플 수 */
} MyCsvFdwPlanState;

/* 실행 상태 구조체 */
typedef struct MyCsvFdwExecState
{
    char       *filename;       /* CSV 파일 경로 */
    FILE       *file;           /* 파일 핸들 */
    char       *buffer;         /* 읽기 버퍼 */
    int         lineno;         /* 현재 줄 번호 */
    AttrNumber  numattrs;       /* 속성 수 */
    FmgrInfo   *in_funcs;       /* 입력 함수 배열 */
    Oid        *typioparams;    /* 타입 IO 매개변수 */
} MyCsvFdwExecState;

#endif /* MY_CSV_FDW_H */
