CREATE FOREIGN TABLE employees (
    id integer,
    name text,
    department text,
    salary numeric
) SERVER csv_server
  OPTIONS (filename '/path/to/employees.csv');

-- 외래 테이블 쿼리
SELECT * FROM employees WHERE department = 'Engineering';

-- EXPLAIN으로 실행 계획 확인
