CREATE INDEX idx_amount_multi ON orders USING brin (amount numeric_minmax_multi_ops);

-- inclusion 연산자 클래스 사용 (기하학적 타입)
CREATE INDEX idx_location ON locations USING brin (bounding_box box_inclusion_ops);
```

