### loki.*

#### loki.source.file

```alloy
loki.source.file "files" {
  targets    = [
    {__path__ = "/var/log/app.log", job = "app"},
    {__path__ = "/var/log/nginx/*.log", job = "nginx"},
  ]
  forward_to = [loki.write.default.receiver]

  decompression {
    enabled       = true
    initial_delay = "10s"
    format        = "gz"
  }
}
```

#### loki.source.kubernetes

```alloy
loki.source.kubernetes "pods" {
  targets    = discovery.kubernetes.pods.targets
  forward_to = [loki.write.default.receiver]
}
```

#### loki.source.journal

```alloy
loki.source.journal "journal" {
  forward_to    = [loki.write.default.receiver]
  max_age       = "12h"
  path          = "/var/log/journal"
  matches       = "_SYSTEMD_UNIT=ssh.service"
  format_as_json = false
  labels = {
    job = "systemd",
  }
}
```

#### loki.source.syslog

```alloy
loki.source.syslog "syslog" {
  listener {
    address  = "0.0.0.0:1514"
    protocol = "tcp"

    tls_config {
      cert_file = "/etc/certs/server.crt"
      key_file  = "/etc/certs/server.key"
    }
  }

  forward_to = [loki.write.default.receiver]
  labels = {
    job = "syslog",
  }
}
```

#### loki.process

```alloy
loki.process "default" {
  forward_to = [loki.write.default.receiver]

  // JSON 파싱
  stage.json {
    expressions = {
      level    = "level",
      msg      = "message",
      duration = "duration",
    }
  }

  // 라벨 추출
  stage.labels {
    values = {
      level = "",
    }
  }

  // logfmt 파싱
  stage.logfmt {
    mapping = {
      method = "",
      path   = "",
      status = "",
    }
  }

  // 정규식
  stage.regex {
    expression = "(?P<ip>\\S+) - - \\[(?P<ts>[^\\]]+)\\] \"(?P<method>\\S+)"
  }

  // 타임스탬프 파싱
  stage.timestamp {
    source = "ts"
    format = "RFC3339"
  }

  // 라인 변환
  stage.output {
    source = "msg"
  }

  // 메트릭 생성
  stage.metrics {
    error_count {
      type        = "Counter"
      description = "Total errors"
      source      = "level"
      config {
        match_all = false
        value     = "error"
        action    = "inc"
      }
    }
  }
}
```

#### loki.relabel

```alloy
loki.relabel "default" {
  forward_to = [loki.write.default.receiver]

  rule {
    source_labels = ["__path__"]
    regex         = ".*\\/(?P<filename>[^\\/]+)\\.log"
    target_label  = "filename"
    replacement   = "$1"
  }
}
```

#### loki.write

```alloy
loki.write "default" {
  endpoint {
    url = "http://loki:3100/loki/api/v1/push"

    headers = {
      "X-Scope-OrgID" = "tenant-1",
    }

    basic_auth {
      username = "user"
      password = sys.env("PASSWORD")
    }

    batch_size = "1MiB"
    batch_wait = "1s"

    max_backoff_period   = "5m"
    max_backoff_retries  = 10
  }

  external_labels = {
    cluster = "prod",
  }
}
```

