  checkAuthToken();
  loadDataFromLocalStorage();
}

function App() {
  // ...
}
```

### 부모 컴포넌트에 state 변경 알리기

```js
// 나쁜 예: Effect에서 늦은 알림
function Toggle({ onChange }) {
  const [isOn, setIsOn] = useState(false);
  useEffect(() => {
    onChange(isOn);
  }, [isOn, onChange]);

  function handleClick() {
    setIsOn(!isOn);
  }
}

// 좋은 예: 이벤트에서 두 컴포넌트 모두 업데이트
function Toggle({ onChange }) {
  const [isOn, setIsOn] = useState(false);

  function updateToggle(nextIsOn) {
    setIsOn(nextIsOn);
    onChange(nextIsOn);
  }

  function handleClick() {
    updateToggle(!isOn);
  }
}

// 최선의 예: 제어 컴포넌트 (state 끌어올리기)
function Toggle({ isOn, onChange }) {
  function handleClick() {
    onChange(!isOn);
  }
}
```

### 외부 저장소 구독하기

```js
// 나쁜 예: Effect에서 수동 구독
function useOnlineStatus() {
  const [isOnline, setIsOnline] = useState(true);
  useEffect(() => {
    function updateState() {
      setIsOnline(navigator.onLine);
    }
    updateState();
    window.addEventListener('online', updateState);
    window.addEventListener('offline', updateState);
    return () => {
      window.removeEventListener('online', updateState);
      window.removeEventListener('offline', updateState);
    };
  }, []);
  return isOnline;
}

// 좋은 예: useSyncExternalStore 사용
function subscribe(callback) {
  window.addEventListener('online', callback);
  window.addEventListener('offline', callback);
  return () => {
    window.removeEventListener('online', callback);
    window.removeEventListener('offline', callback);
  };
}

function useOnlineStatus() {
  return useSyncExternalStore(
    subscribe,
    () => navigator.onLine,  // 클라이언트에서 값 가져오는 방법
    () => true               // 서버에서 값 가져오는 방법
  );
}
```

### 데이터 가져오기

```js
// 경쟁 상태가 있는 코드
function SearchResults({ query }) {
  const [results, setResults] = useState([]);
  const [page, setPage] = useState(1);

  useEffect(() => {
    fetchResults(query, page).then(json => {
      setResults(json);
    });
  }, [query, page]);
}

// 정리 함수로 오래된 응답 무시
function SearchResults({ query }) {
  const [results, setResults] = useState([]);
  const [page, setPage] = useState(1);

  useEffect(() => {
    let ignore = false;
    fetchResults(query, page).then(json => {
      if (!ignore) {
        setResults(json);
      }
    });
    return () => {
      ignore = true;
    };
  }, [query, page]);
}
```

**커스텀 Hook으로 재사용 가능한 데이터 가져오기:**

```js
function useData(url) {
  const [data, setData] = useState(null);
  useEffect(() => {
    let ignore = false;
    fetch(url)
      .then(response => response.json())
      .then(json => {
        if (!ignore) {
          setData(json);
        }
      });
    return () => {
      ignore = true;
    };
  }, [url]);
  return data;
}

function SearchResults({ query }) {
  const [page, setPage] = useState(1);
  const params = new URLSearchParams({ query, page });
  const results = useData(`/api/search?${params}`);

  function handleNextPageClick() {
    setPage(page + 1);
  }
}
```

### 핵심 원칙 정리

- 렌더링 중에 계산할 수 있으면 Effect가 필요 없음
- 비싼 계산을 캐시하려면 `useEffect` 대신 `useMemo`를 사용할 것
- 전체 컴포넌트 트리의 state를 재설정하려면 다른 `key`를 전달할 것
- prop 변경에 대응하여 특정 state를 재설정하려면 렌더링 중에 설정할 것
- 컴포넌트가 표시되었기 때문에 실행해야 하는 코드는 Effect에, 나머지는 이벤트에 넣을 것
- 여러 컴포넌트의 state를 업데이트해야 하면 단일 이벤트에서 할 것
- 서로 다른 컴포넌트의 state 변수를 동기화하려 할 때마다 state 끌어올리기를 고려할 것
- Effect로 데이터를 가져올 수 있지만, 경쟁 상태를 피하기 위해 정리를 구현해야 함

